    methods (Access = private)

        function diam = calculate_diam(app, A)
            %stats = regionprops(app.bw_caps,'Centroid');
            %app.dist_caps = ((stats(1).Centroid(1)-stats(2).Centroid(1)).^2+(stats(1).Centroid(2)-stats(2).Centroid(2)).^2).^0.5;
            app.dist_caps = find_dist_caps(app.bw_caps, app.mask, app.seg);
            diam = A / app.dist_caps;

            %app.fs = 1 / mean(diff(app.t));
            if isempty(app.t)
                app.t = (1:length(diam))/app.fs;
            end
            figure, plot(diam), ylabel('diam (pixels)'), xlabel('frame #')
            %figure, spectrogram(highpass(A,0.5,fs),round(15*fs),[],[],fs,'yaxis'), title('Area')
            %figure, spectrogram(highpass(squeeze(mean(app.img,[1 2])),0.5,fs),round(15*fs),[],[],fs,'yaxis'), title('MPI')
            %figure, spectrogram(A,round(15*fs),[],[],fs,'yaxis'), title('Area')
            %figure, spectrogram(squeeze(mean(app.img,[1 2])),round(15*fs),[],[],fs,'yaxis'), title('MPI')
        end

        function A = calculate_area(app)
            A = squeeze(sum(app.seg,[1 2]));
            figure, set(gcf,'color','w')
            plot(A), ylabel('Area (pixels)'), xlabel('frame #')
        end


