        function [] = readLIF(app, imgList, LIFSeriesNumber)

            dat=cell(1,5);
            dat{1,1}=imgList(LIFSeriesNumber).Name;           % Name of image
            dat{1,2}=numel(imgList(LIFSeriesNumber).Channels);% number of channel
            [dimType, dimSize]=GetDimensionInfo(imgList(LIFSeriesNumber).Dimensions);
            dat{1,3}=dimType;
            dat{1,4}=int2str(dimSize');
            dat{1,5}=false;

            framerange = [1 inf];
            % -=- Set up framerange -=-
            if strcmp('X-Y-T',dat{1,3})
                framerange=[max([framerange(1) 1]) ... % first frame is 1, not 0!
                    min([framerange(2) ...
                    str2double(imgList(LIFSeriesNumber).Dimensions(3).NumberOfElements)])];
            else
                warning('Framerange is supported only for X-Y-T data.')
                framerange=[0 imgList(LIFSeriesNumber).Dimensions(3).NumberOfElements];
            end
            if str2double(imgList(LIFSeriesNumber).Dimensions(3).BitInc)~=0
                warning('Framerange is supported only for BitInc=0.')
                framerange=[0 imgList(LIFSeriesNumber).Dimensions(3).NumberOfElements];
            end

            imgData  = ReadAnImageData(imgList(LIFSeriesNumber),app.filePath,framerange);
            imgStruct= ReconstructImage(imgList(LIFSeriesNumber),imgData,framerange);
            imgStruct.Name            = dat{1,1};
            imgStruct.Type            = dat{1,3};
            imgStruct.NumberOfChannel = dat{1,2};
            imgStruct.AllocatedFrames=imgList(LIFSeriesNumber).Dimensions(3).NumberOfElements;
            imgStruct.SeriesNames = {dat{:,1}};
            dt = str2double(imgStruct.Info.Dimensions(3).Length) / ...
                str2double(imgStruct.Info.Dimensions(3).NumberOfElements);
            imgStruct.Info.Dimensions(3).NumberOfElements = ...
                num2str(size(imgStruct.Image{1},4));
            imgStruct.Info.Dimensions(3).Origin = ...
                num2str((framerange(1)-1)*dt,'%01.6e');
            imgStruct.Info.Dimensions(3).Length = ...
                num2str((diff(framerange)+1)*dt,'%01.6e');
            imgout=imgStruct;

            app.fs = str2num(imgout.Info.Dimensions(3).NumberOfElements)/str2num(imgout.Info.Dimensions(3).Length);
            app.t = [0:str2num(imgout.Info.Dimensions(3).NumberOfElements)-1]/app.fs;
            app.umperpix = app.LIFSeriesPanel_UmPerPixEditField.Value;
            if app.umperpix == 0
                app.umperpix = 1e6*str2num(imgout.Info.Dimensions(2).Length)/str2num(imgout.Info.Dimensions(2).NumberOfElements);
            end
            app.img = squeeze(imgout.Image{1});
        end

        function tiffData = readTif(app, tiffPath)
            reader = bfGetReader(tiffPath);
            %nSeries = reader.getSeriesCount();
            nFrames = reader.getImageCount();
            height = reader.getSizeY();
            width  = reader.getSizeX();
            %bitDepth = reader.getBitsPerPixel();  % optional
            dtype = 'uint16';  % change if needed

            % Preallocate
            tiffData = zeros(height, width, nFrames, dtype);

            % Disable logging (silence the verbose plane info)
            loci.common.DebugTools.enableLogging('ERROR');  % suppress INFO logs

            % Read all frames
            for i = 1:nFrames
                tiffData(:,:,i) = bfGetPlane(reader, i);
            end

            reader.close();

        end

        function dsFactor = setDSFactor(app)
            imageSize = size(app.img);
            nFrames = imageSize(3);
            dsFactor = 100;
            if nFrames/app.maxPreviewFrames > dsFactor
                dsFactor = round(nFrames/app.maxPreviewFrames);
            else
                dsFactor = max(1, round(nFrames/app.maxPreviewFrames));
            end
        end
    end

    methods (Access = public)

