        % Button pushed function: SelectDirectoryButton
        function SelectDirectoryButtonPushed(app, event)
            f = figure('Position', [-100 -100 0 0]); % create a dummy figure so that uigetfile doesn't minimize our GUI
            %selectedDir = uigetdir(app.currentDir);
            [selectedFile, parentFolder] = uigetfile({'*.lif;*.mat;*.tif'});
            %[parentFolder, ~, ~] = fileparts(string(selectedDir));

            app.defaultUigetdir = parentFolder;
            % Check if a directory was selected (uigetdir returns 0 if the user cancels the dialog)
            delete(f);
            if selectedFile ~= 0
                % Store the selected directory path in the Edit Field
                app.filePath = fullfile(parentFolder, selectedFile);
                app.SelectDirectoryTextArea.Value = app.filePath;
            end
        end

        % Button pushed function: HomePanel_ContinueButton
        function HomePanel_ContinueButtonPushed(app, event)
            [filepath, name, ext] = fileparts(app.filePath);
            if strcmp(ext, '.lif')
                fileID = fopen(app.filePath, 'r');
                [fp, xmlHdrStr] = ReadXMLPart(fileID);
                xmlList=XMLtxt2cell(xmlHdrStr);
                lifVersion = GetLifVersion(xmlList(1,:)); % lifVersion is double scalar

                % Reading Image Info
                imgList = GetImageDescriptionList(xmlList);% imgList is struct vector
                % memoryList is cell array (n x 4)
                % ID(string), startPoint(uint64), sizeOfMemory, Index(double)
                imgList  = ReadObjectMemoryBlocks(fp,lifVersion,imgList);
                fclose(fp);
                app.seriesCount = numel(imgList);
                message = '';
                for n=1:app.seriesCount
                    message = [message, {strcat(int2str(n), '. ', imgList(n).Name)}];
                end
                app.LIFSeriesPanel_TextArea.Value = message;
                app.HomePanel.Visible = 'off';
                app.LIFSeriesPanel.Visible = 'on';
                app.waitingForInput = true;
                waitfor(app, 'waitingForInput', false);

                LIFSeriesNumber = app.LIFSeriesPanel_LIFSeriesNumberEditField.Value;
                readLIF(app, imgList, LIFSeriesNumber)
            elseif strcmp(ext, '.mat')
                app.HomePanel.Visible = 'off';
                app.img = load(app.filePath).img;

            elseif strcmp(ext, '.tif')
                app.HomePanel.Visible = 'off';
                app.LIFSeriesPanel.Visible = 'off';
                app.TIFFrequencyPanel.Visible = 'on';
                app.waitingForInput = true;
                waitfor(app, 'waitingForInput', false);

                app.fs = app.TIFFrequencyPanel_FrequencyEditField.Value;
                app.umperpix = app.TIFFrequencyPanel_UmPerPixEditField.Value;

                try
                    [app.img, ~] = imread_big(app.filePath);
                catch
                    warning('imread_big failed; falling back to imread loop.');
                    numImages = size(imfinfo(app.filePath), 1);
                    imageSize = size(imread(app.filePath));
                    app.img = zeros(imageSize(1), imageSize(2), numImages);
                    for i = 1:numImages
                        app.img(:, :, i) = imread(app.filePath,i);
                    end
                end

            end

            app.dsFactor = setDSFactor(app);
            images = app.img(:, :, 1:app.dsFactor:end);
            % cropping
            %app.LIFSeriesPanel.Visible = 'off';
            %app.TIFFrequencyPanel.Visible = 'off';
            app.CroppingPanel.Visible = 'on';
            imagei(images), colormap gray
            roi = drawrectangle();
            wait(roi);
            app.rect = round(roi.Position);
            images = images(app.rect(2):app.rect(2)+app.rect(4),app.rect(1):app.rect(1)+app.rect(3),:);
            closePopup(app)
            %app.ThresholdPanel.Visible = 'on';
            app.CroppingPanel.Visible = 'off';
            app.waitingForInput = true;
            %[app.e, app.seg, app.bw_caps, app.mask] = find_img_edges(app, app.img, [], 1);
            images = findEdges(app, images);
            images = makeMask(app, images);
            %dilateMask(app)
            images = makeCaps(app, images);
            app.SliceProgressPanel.Visible = 'on';
            images = makeSeg(app, images);
            imagei({images images images},{repmat(app.bw_caps | app.mask,[1 1 size(app.seg,3)]) app.seg app.e})

        end

