        % Button pushed function: SaveResultsButton
        function SaveResultsButtonPushed(app, event)
            f = figure('Position', [-100 -100 0 0]); % create a dummy figure so that uigetfile doesn't minimize our GUI
            %selectedDir = uigetdir(app.currentDir);
            [~,name,~] = fileparts(app.filePath);
            defaultSaveName = [name '_results.mat'];
            [filename, path] = uiputfile(defaultSaveName);
            % Check if a directory was selected (uigetdir returns 0 if the user cancels the dialog)
            delete(f);
            if path ~= 0
                % Create the full file path
                full_file_path = fullfile(path, filename);
                full_file_path = string(full_file_path);
                %app.SliceProgressPanel_Label.Text = full_file_path;
                % Save the data
                t = app.t;
                fs = app.fs;
                umperpix = app.umperpix;
                img = app.img;
                rect = app.rect;
                area = app.area;
                bw_caps = app.bw_caps;
                mask = app.mask;
                e = app.e;
                seg = app.seg;
                diam = app.diam;
                dist_caps = app.dist_caps;
                save(full_file_path, ...
                    "t", ...
                    "fs", ...
                    "umperpix", ...
                    "img", ...
                    'rect', ...
                    'area', ...
                    'bw_caps', ...
                    'mask', ...
                    'e', ...
                    'seg', ...
                    'diam', ...
                    'dist_caps', ...
                    '-v7.3' ...
                );
                message = strcat("results saved to ", full_file_path);
                title = 'Results Saved';
                icon = 'success';
                uialert(app.UIFigure, message, title, 'Icon', icon);


                app.RunComputationPanel.Visible = 'off';
                app.HomePanel.Visible = 'on';
                resetApp(app)
            end
        end

        % Button pushed function: RunButton
        function RunButtonPushed(app, event)
            app.img = app.img(app.rect(2):app.rect(2)+app.rect(4),app.rect(1):app.rect(1)+app.rect(3),:);

            findEdges(app, app.img);
            makeMask(app, app.img);
            app.SliceProgressPanel.Visible = 'on';
            makeSeg(app, app.img);
            app.SliceProgressPanel.Visible = 'off';
            app.RunComputationPanel.Visible = 'on'; % gather the user input from panel_2

            app.RunComputationPanel_TextArea.Value = 'Masks and caps created.';
            message = 'calculating area and diameter.';
            app.RunComputationPanel_TextArea.Value = [app.RunComputationPanel_TextArea.Value(:)', {message}];
            app.waitingForInput = true;
            %[app.e, app.seg, app.bw_caps, app.mask] = find_img_edges(app, app.img, app.bw_caps, app.mask);
            app.area = calculate_area(app);
            app.diam = calculate_diam(app, app.area);
            message = 'Done.';
            app.RunComputationPanel_TextArea.Value = [app.RunComputationPanel_TextArea.Value(:)', {message}];
        end

        % Button pushed function: RedoMaskButton
        function RedoMaskButtonPushed(app, event)
            clearUserInput(app)
            app.waitingForInput = true;

            app.dsFactor = setDSFactor(app);
            images = app.img(:, :, 1:app.dsFactor:end);
            images = images(app.rect(2):app.rect(2)+app.rect(4),app.rect(1):app.rect(1)+app.rect(3),:);

            images = findEdges(app, images);
            images = makeMask(app, images);
            %dilateMask(app)
            images = makeCaps(app, images);
            app.SliceProgressPanel.Visible = 'on';
            images = makeSeg(app, images);
            imagei({images images images},{repmat(app.bw_caps | app.mask,[1 1 size(app.seg,3)]) app.seg app.e})
        end

        % Button pushed function: LIFSeriesPanel_NextButton
        function LIFSeriesPanel_NextButtonPushed(app, event)
            lifSeriesNum = app.LIFSeriesPanel_LIFSeriesNumberEditField.Value;
            message = '';
            if lifSeriesNum > app.seriesCount
                message = strcat('The series index you entered is greater than the number of series, ', int2str(app.seriesCount), ', in the LIF.');
            elseif lifSeriesNum < 1
                message = 'The series index starts at 1.';
            end

            if (message ~= "")
                uialert(app.UIFigure, message, "Invalid Value");
            else
            app.LIFSeriesPanel.Visible = 'off';
            app.TIFFrequencyPanel.Visible = 'off';
            app.waitingForInput = false;
            end
        end

        % Button pushed function: TIFFrequencyPanel_NextButton
        function TIFFrequencyPanel_NextButtonPushed(app, event)
            frequency = app.TIFFrequencyPanel_FrequencyEditField.Value;
            message = '';
            if frequency <= 0
                message = 'Frequency must be greater than 0.';
            end

            if (message ~= "")
                uialert(app.UIFigure, message, "Invalid Value");
            else
            app.TIFFrequencyPanel.Visible = 'off';
            app.waitingForInput = false;
            end
        end
    end

